register_rest_route(
	$this->namespace,
	'/' . $this->rest_base,
	array(
		array(
			'methods'             => WP_REST_Server::READABLE,
			'callback'            => array( $this, 'get_items' ),
			'permission_callback' => array( $this, 'get_items_permissions_check' ),
			'args'                => $this->get_collection_params(),
		),
		'schema' => array( $this, 'get_public_item_schema' ),
	)
);

register_rest_route(
	$this->namespace,
	'/' . $this->rest_base . '/(?P<location>[\w-]+)',
	array(
		'args'   => array(
			'location' => array(
				'description' => __( 'An alphanumeric identifier for the menu location.', 'kubio' ),
				'type'        => 'string',
			),
		),
		array(
			'methods'             => WP_REST_Server::READABLE,
			'callback'            => array( $this, 'get_item' ),
			'permission_callback' => array( $this, 'get_item_permissions_check' ),
			'args'                => array(
				'context' => $this->get_context_param( array( 'default' => 'view' ) ),
			),
		),
		'schema' => array( $this, 'get_public_item_schema' ),
	)
);

register_rest_route(
	$this->namespace,
	'/' . $this->rest_base,
	array(
		array(
			'methods'             => WP_REST_Server::READABLE,
			'callback'            => array( $this, 'get_items' ),
			'permission_callback' => array( $this, 'get_permissions' ),
			'args'                => $this->get_collection_params(),
		),

		'schema' => array( $this, 'get_public_item_schema' ),
	)
);

register_rest_route(
	$this->namespace,
	'/' . $this->rest_base . '/save-menu-location',
	array(
		array(
			'methods'             => WP_REST_Server::CREATABLE,
			'callback'            => array( $this, 'set_menu_to_location' ),
			'permission_callback' => array( $this, 'get_permissions' ),
			'args'                => $this->get_endpoint_args_for_item_schema( WP_REST_Server::CREATABLE ),
		),

		'schema' => array( $this, 'get_public_item_schema' ),
	)
);

